284: func StageAllChanges(options StageAllChangesOptions) (StageAllChangesResult, error) {
285: 	inspectOptions := InspectOptions{
286: 		CWD:          options.CWD,
287: 		MaxDiffBytes: options.MaxDiffBytes,
288: 		Env:          options.Env,
289: 		GitRunner:    options.GitRunner,
290: 	}
291: 
292: 	if !options.Confirmed {
293: 		inspection, err := InspectRepository(inspectOptions)
294: 		return StageAllChangesResult{Staged: false, Reason: "not_confirmed", Inspection: inspection}, err
295: 	}
296: 
297: 	if !options.IsTTY {
298: 		inspection, err := InspectRepository(inspectOptions)
299: 		return StageAllChangesResult{Staged: false, Reason: "non_tty", Inspection: inspection}, err
300: 	}
301: 
302: 	gitRunner := options.GitRunner
303: 	if gitRunner == nil {
304: 		gitRunner = DefaultCommandRunner
305: 	}
306: 	addResult := normalizeRunnerResult(gitRunner(options.CWD, []string{"add", "-A"}, options.Env))
307: 	if addResult.ExitCode != 0 {
308: 		inspection, err := InspectRepository(inspectOptions)
309: 		inspection = addBlockingIssue(inspection, createIssue("git_add_failed", formatGitFailure("git add -A", addResult.Stderr, addResult.Stdout), IssueSeverityBlocking))
310: 		return StageAllChangesResult{Staged: false, Reason: "git_add_failed", Inspection: inspection}, err
311: 	}
312: 
313: 	inspection, err := InspectRepository(inspectOptions)
314: 	return StageAllChangesResult{Staged: true, Reason: "confirmed", Inspection: inspection}, err
315: }
