361: func CommitScopeWithMessage(options CommitScopeCommitOptions) (CommitScopeCommitResult, error) {
362: 	gitRunner := options.GitRunner
363: 	if gitRunner == nil {
364: 		gitRunner = DefaultCommandRunner
365: 	}
366: 	if strings.TrimSpace(options.Message) == "" {
367: 		return CommitScopeCommitResult{Git: CommandResult{ExitCode: 1, Stderr: "commit message is required"}}, nil
368: 	}
369: 	if len(options.Scope.Files) == 0 {
370: 		return CommitScopeCommitResult{Git: CommandResult{ExitCode: 1, Stderr: "no selected changes"}}, nil
371: 	}
372: 
373: 	addArgs := []string{"add", "--"}
374: 	for _, file := range options.Scope.Files {
375: 		addArgs = append(addArgs, file.Path)
376: 	}
377: 	addResult := normalizeRunnerResult(gitRunner(options.CWD, addArgs, options.Env))
378: 	if addResult.ExitCode != 0 {
379: 		return CommitScopeCommitResult{Message: options.Message, Git: addResult}, nil
380: 	}
381: 
382: 	commitResult, err := commitWithMessageOptions(options.CWD, options.Message, options.Env, gitRunner, options.NoVerify)
383: 	if err != nil {
384: 		return CommitScopeCommitResult{}, err
385: 	}
386: 	if commitResult.ExitCode != 0 {
387: 		return CommitScopeCommitResult{Message: options.Message, Git: commitResult}, nil
388: 	}
389: 	headResult := normalizeRunnerResult(gitRunner(options.CWD, []string{"rev-parse", "HEAD"}, options.Env))
390: 	hash := strings.TrimSpace(headResult.Stdout)
391: 	return CommitScopeCommitResult{Hash: hash, Message: options.Message, Git: commitResult}, nil
392: }
