131: func InspectCommitScope(options CommitScopeOptions) (CommitScope, error) {
132: 	maxDiffBytes := options.MaxDiffBytes
133: 	if maxDiffBytes <= 0 {
134: 		maxDiffBytes = DefaultMaxDiffBytes
135: 	}
136: 	maxReadBytes := options.MaxReadBytes
137: 	if maxReadBytes <= 0 {
138: 		maxReadBytes = DefaultMaxReadBytes
139: 	}
140: 	contextPolicy := ContextPolicy{Mode: ContextPolicyModeBounded, FileReadsAllowed: true}
141: 	if options.DiffOnly {
142: 		contextPolicy = ContextPolicy{Mode: ContextPolicyModeDiffOnly, FileReadsAllowed: false}
143: 	}
144: 	gitRunner := options.GitRunner
145: 	if gitRunner == nil {
146: 		gitRunner = DefaultCommandRunner
147: 	}
148: 
149: 	statusArgs := []string{"status", "--porcelain=v1", "-z", "--untracked-files=all"}
150: 	if len(options.Pathspecs) > 0 {
151: 		statusArgs = append(statusArgs, "--")
152: 		statusArgs = append(statusArgs, options.Pathspecs...)
153: 	}
154: 	statusResult := normalizeRunnerResult(gitRunner(options.CWD, statusArgs, options.Env))
155: 	if statusResult.ExitCode != 0 {
156: 		return CommitScope{}, fmt.Errorf("%s", formatGitFailure("git status --porcelain", statusResult.Stderr, statusResult.Stdout))
157: 	}
158: 
159: 	files := parsePorcelainStatus(statusResult.Stdout)
160: 	cachedNumstatResult := normalizeRunnerResult(gitRunner(options.CWD, scopedGitArgs([]string{"diff", "--cached", "--numstat", "-z", "--find-renames"}, options.Pathspecs), options.Env))
161: 	worktreeNumstatResult := normalizeRunnerResult(gitRunner(options.CWD, scopedGitArgs([]string{"diff", "--numstat", "-z", "--find-renames"}, options.Pathspecs), options.Env))
162: 	if cachedNumstatResult.ExitCode == 0 {
163: 		files = applyBinaryMetadata(files, cachedNumstatResult.Stdout)
164: 	}
165: 	if worktreeNumstatResult.ExitCode == 0 {
166: 		files = applyBinaryMetadata(files, worktreeNumstatResult.Stdout)
167: 	}
168: 	files = applyWorkingTreeBinaryMetadata(options.CWD, files)
169: 	diffResult := normalizeRunnerResult(gitRunner(options.CWD, scopedGitArgs([]string{"diff", "--patch", "--binary", "--find-renames"}, options.Pathspecs), options.Env))
170: 	_, diffMetadata := truncateDiff("", maxDiffBytes)
171: 	if diffResult.ExitCode == 0 {
172: 		_, diffMetadata = truncateDiff(diffResult.Stdout, maxDiffBytes)
173: 	}
174: 	headResult := normalizeRunnerResult(gitRunner(options.CWD, []string{"rev-parse", "--verify", "HEAD"}, options.Env))
175: 	var head *string
176: 	if headResult.ExitCode == 0 && strings.TrimSpace(headResult.Stdout) != "" {
177: 		head = stringPtr(strings.TrimSpace(headResult.Stdout))
178: 	}
179: 	stagedFiles := filterFiles(files, func(file FileStatus) bool { return file.Staged != nil })
180: 	selected := make([]FileStatus, 0, len(files))
181: 	for _, file := range files {
182: 		if options.StagedOnly {
183: 			if file.Staged != nil {
184: 				selected = append(selected, file)
185: 			}
186: 			continue
187: 		}
188: 		if file.Untracked && !options.IncludeUntracked {
189: 			continue
190: 		}
191: 		if file.Staged != nil || file.Unstaged != nil || file.Untracked {
192: 			selected = append(selected, file)
193: 		}
194: 	}
195: 	sort.Slice(selected, func(i, j int) bool { return selected[i].Path < selected[j].Path })
196: 	readUsage := BudgetUsage{MaxBytes: maxReadBytes}
197: 	secretBlockers := []ScopedSecretFinding{}
198: 	if contextPolicy.FileReadsAllowed {
199: 		var usedReadBytes int
200: 		secretBlockers, usedReadBytes = scanScopeSecrets(options.CWD, selected, maxReadBytes)
201: 		readUsage.UsedBytes = usedReadBytes
202: 	}
203: 	exposure := buildAIExposureSummary(selected, secretBlockers, diffMetadata, readUsage, options.PreferenceSources)
204: 
205: 	return CommitScope{
206: 		Files:              selected,
207: 		Pathspecs:          append([]string{}, options.Pathspecs...),
208: 		StagedOnly:         options.StagedOnly,
209: 		IncludesUntracked:  options.IncludeUntracked,
210: 		HasSelectedChanges: len(selected) > 0,
211: 		IndexSnapshot:      &IndexSnapshot{Head: head, StagedFiles: stagedFiles},
212: 		SecretBlockers:     secretBlockers,
213: 		ContextPolicy:      contextPolicy,
214: 		AIExposure:         exposure,
215: 	}, nil
216: }
