250: func buildAIExposureSummary(files []FileStatus, secretBlockers []ScopedSecretFinding, diffMetadata DiffMetadata, readUsage BudgetUsage, preferenceSources PreferenceExposure) AIExposureSummary {
251: 	opaqueChanges := make([]OpaqueChangeSummary, 0)
252: 	visibleFiles := make([]ProviderVisibleFile, 0, len(files))
253: 	for _, file := range files {
254: 		visible := ProviderVisibleFile{Path: file.Path, Source: "diff", Opaque: file.Binary}
255: 		if file.Untracked {
256: 			visible.Source = "metadata"
257: 		}
258: 		if file.Binary {
259: 			visible.Source = "metadata"
260: 		}
261: 		visibleFiles = append(visibleFiles, visible)
262: 		if file.Binary {
263: 			opaqueChanges = append(opaqueChanges, OpaqueChangeSummary{Path: file.Path, Reason: "binary"})
264: 		}
265: 	}
266: 	return AIExposureSummary{
267: 		SelectedFileCount:    len(files),
268: 		OpaqueChangeCount:    len(opaqueChanges),
269: 		SecretBlockerCount:   len(secretBlockers),
270: 		ProviderVisibleFiles: visibleFiles,
271: 		PreferenceSources:    preferenceSources,
272: 		DiffBudget: BudgetUsage{
273: 			MaxBytes:      diffMetadata.MaxBytes,
274: 			UsedBytes:     diffMetadata.Bytes,
275: 			OriginalBytes: diffMetadata.OriginalBytes,
276: 			Truncated:     diffMetadata.Truncated,
277: 			OmittedBytes:  diffMetadata.OmittedBytes,
278: 		},
279: 		ReadBudget:    readUsage,
280: 		OpaqueChanges: opaqueChanges,
281: 	}
282: }
