218: func scanScopeSecrets(cwd string, files []FileStatus, maxReadBytes int) ([]ScopedSecretFinding, int) {
219: 	findings := make([]ScopedSecretFinding, 0)
220: 	usedReadBytes := 0
221: 	for _, file := range files {
222: 		if file.Binary || file.Staged != nil && file.Unstaged == nil && !file.Untracked {
223: 			// Staged-only content is scanned through staged diffs later; this baseline
224: 			// scanner handles working tree files for the new Commit Scope path.
225: 			continue
226: 		}
227: 		content, err := os.ReadFile(filepath.Join(cwd, file.Path))
228: 		if err != nil || bytes.IndexByte(content, 0) >= 0 {
229: 			continue
230: 		}
231: 		if maxReadBytes > 0 && usedReadBytes+len(content) > maxReadBytes {
232: 			continue
233: 		}
234: 		usedReadBytes += len(content)
235: 		scan := security.ScanTextForSecrets(string(content))
236: 		for _, finding := range scan.Findings {
237: 			findings = append(findings, ScopedSecretFinding{
238: 				Path:        file.Path,
239: 				Code:        finding.Code,
240: 				Description: finding.Description,
241: 				Line:        finding.Line,
242: 				Excerpt:     finding.Excerpt,
243: 				Severity:    finding.Severity,
244: 			})
245: 		}
246: 	}
247: 	return findings, usedReadBytes
248: }
