 18: func DefaultCommandRunner(cwd string, args []string, env map[string]string) (CommandResult, error) {
 19: 	command := exec.Command("git", args...)
 20: 	command.Dir = cwd
 21: 	command.Env = mergeEnv(env)
 22: 
 23: 	var stdout bytes.Buffer
 24: 	var stderr bytes.Buffer
 25: 	command.Stdout = &stdout
 26: 	command.Stderr = &stderr
 27: 
 28: 	err := command.Run()
 29: 	result := CommandResult{
 30: 		Stdout: strings.TrimRight(stdout.String(), "\n"),
 31: 		Stderr: strings.TrimRight(stderr.String(), "\n"),
 32: 	}
 33: 
 34: 	if err == nil {
 35: 		result.ExitCode = 0
 36: 		return result, nil
 37: 	}
 38: 
 39: 	var exitError *exec.ExitError
 40: 	if ok := asExitError(err, &exitError); ok {
 41: 		result.ExitCode = exitError.ExitCode()
 42: 		return result, nil
 43: 	}
 44: 
 45: 	result.ExitCode = 1
 46: 	if result.Stderr == "" {
 47: 		result.Stderr = err.Error()
 48: 	}
 49: 	return result, nil
 50: }
