 52: func InspectRepository(options InspectOptions) (Inspection, error) {
 53: 	maxDiffBytes := options.MaxDiffBytes
 54: 	if maxDiffBytes <= 0 {
 55: 		maxDiffBytes = DefaultMaxDiffBytes
 56: 	}
 57: 	gitRunner := options.GitRunner
 58: 	if gitRunner == nil {
 59: 		gitRunner = DefaultCommandRunner
 60: 	}
 61: 
 62: 	repository := detectRepository(options.CWD, options.Env, gitRunner)
 63: 	if !repository.IsRepository || repository.IsBare {
 64: 		emptyDiff, metadata := truncateDiff("", maxDiffBytes)
 65: 		files := []FileStatus{}
 66: 		issues := buildIssues(repository, files, metadata)
 67: 		warnings, blockingIssues := splitIssues(issues)
 68: 		return Inspection{
 69: 			Repository:         repository,
 70: 			Files:              files,
 71: 			StagedFiles:        []FileStatus{},
 72: 			UnstagedFiles:      []FileStatus{},
 73: 			UntrackedFiles:     []FileStatus{},
 74: 			StagedDiff:         emptyDiff,
 75: 			Diff:               metadata,
 76: 			SecretScan:         security.ScanTextForSecrets(emptyDiff),
 77: 			Issues:             issues,
 78: 			Warnings:           warnings,
 79: 			BlockingIssues:     blockingIssues,
 80: 			HasStagedChanges:   false,
 81: 			HasUnstagedChanges: false,
 82: 			HasUntrackedFiles:  false,
 83: 		}, nil
 84: 	}
 85: 
 86: 	statusResult := normalizeRunnerResult(gitRunner(options.CWD, []string{"status", "--porcelain=v1", "-z", "--untracked-files=all"}, options.Env))
 87: 	numstatResult := normalizeRunnerResult(gitRunner(options.CWD, []string{"diff", "--cached", "--numstat", "-z", "--find-renames"}, options.Env))
 88: 	diffResult := normalizeRunnerResult(gitRunner(options.CWD, []string{"diff", "--cached", "--patch", "--binary", "--find-renames"}, options.Env))
 89: 
 90: 	commandIssues := make([]Issue, 0, 3)
 91: 	if statusResult.ExitCode != 0 {
 92: 		commandIssues = append(commandIssues, createIssue("git_status_failed", formatGitFailure("git status --porcelain", statusResult.Stderr, statusResult.Stdout), IssueSeverityBlocking))
 93: 	}
 94: 	if numstatResult.ExitCode != 0 {
 95: 		commandIssues = append(commandIssues, createIssue("git_diff_numstat_failed", formatGitFailure("git diff --cached --numstat", numstatResult.Stderr, numstatResult.Stdout), IssueSeverityBlocking))
 96: 	}
 97: 	if diffResult.ExitCode != 0 {
 98: 		commandIssues = append(commandIssues, createIssue("git_diff_patch_failed", formatGitFailure("git diff --cached --patch", diffResult.Stderr, diffResult.Stdout), IssueSeverityBlocking))
 99: 	}
100: 
101: 	files := applyBinaryMetadata(parsePorcelainStatus(statusResult.Stdout), numstatResult.Stdout)
102: 	stagedFiles := filterFiles(files, func(file FileStatus) bool { return file.Staged != nil })
103: 	unstagedFiles := filterFiles(files, func(file FileStatus) bool { return file.Unstaged != nil })
104: 	untrackedFiles := filterFiles(files, func(file FileStatus) bool { return file.Untracked })
105: 	truncatedDiff, diffMetadata := truncateDiff(diffResult.Stdout, maxDiffBytes)
106: 	secretScan := security.ScanTextForSecrets(diffResult.Stdout)
107: 	issues := append(buildIssues(repository, files, diffMetadata), commandIssues...)
108: 	if len(secretScan.Findings) > 0 {
109: 		issues = append(issues, createIssue("secret_scan_match", "Potential secrets were found in inspected diff content.", IssueSeverityWarning))
110: 	}
111: 	warnings, blockingIssues := splitIssues(issues)
112: 
113: 	return Inspection{
114: 		Repository:         repository,
115: 		Files:              files,
116: 		StagedFiles:        stagedFiles,
117: 		UnstagedFiles:      unstagedFiles,
118: 		UntrackedFiles:     untrackedFiles,
119: 		StagedDiff:         truncatedDiff,
120: 		Diff:               diffMetadata,
121: 		SecretScan:         secretScan,
122: 		Issues:             issues,
123: 		Warnings:           warnings,
124: 		BlockingIssues:     blockingIssues,
125: 		HasStagedChanges:   len(stagedFiles) > 0,
126: 		HasUnstagedChanges: len(unstagedFiles) > 0,
127: 		HasUntrackedFiles:  len(untrackedFiles) > 0,
128: 	}, nil
