310: 		return StageAllChangesResult{Staged: false, Reason: "git_add_failed", Inspection: inspection}, err
311: 	}
312: 
313: 	inspection, err := InspectRepository(inspectOptions)
314: 	return StageAllChangesResult{Staged: true, Reason: "confirmed", Inspection: inspection}, err
315: }
316: 
317: func GetRecentCommits(cwd string, env map[string]string, limit int, gitRunner CommandRunner) ([]string, error) {
318: 	if limit <= 0 {
319: 		limit = 10
320: 	}
321: 	if gitRunner == nil {
322: 		gitRunner = DefaultCommandRunner
323: 	}
324: 	result := normalizeRunnerResult(gitRunner(cwd, []string{"log", fmt.Sprintf("--max-count=%d", limit), "--pretty=format:%s%n%b", "--no-merges"}, env))
325: 	if result.ExitCode != 0 {
326: 		return []string{}, nil
327: 	}
328: 
329: 	commits := make([]string, 0)
330: 	for _, commit := range strings.Split(result.Stdout, "\n\n") {
331: 		trimmed := strings.TrimSpace(commit)
332: 		if trimmed != "" {
333: 			commits = append(commits, trimmed)
334: 		}
335: 	}
336: 	if len(commits) > limit {
337: 		commits = commits[:limit]
338: 	}
339: 	return commits, nil
340: }
