342: func CommitWithMessage(cwd, message string, env map[string]string, gitRunner CommandRunner) (CommandResult, error) {
343: 	if gitRunner == nil {
344: 		gitRunner = DefaultCommandRunner
345: 	}
346: 
347: 	tempDir, err := os.MkdirTemp("", "cnm-commit-")
348: 	if err != nil {
349: 		return CommandResult{ExitCode: 1, Stderr: err.Error()}, nil
350: 	}
351: 	defer os.RemoveAll(tempDir)
352: 
353: 	messagePath := filepath.Join(tempDir, "COMMIT_EDITMSG")
354: 	if err := os.WriteFile(messagePath, []byte(strings.TrimSpace(message)+"\n"), 0o600); err != nil {
355: 		return CommandResult{ExitCode: 1, Stderr: err.Error()}, nil
356: 	}
357: 
358: 	return normalizeRunnerResult(gitRunner(cwd, []string{"commit", "-F", messagePath}, env)), nil
359: }
