15: func defaultHTTPClient() HTTPDoer {
16: 	return &http.Client{Timeout: 60 * time.Second}
17: }
18: 
19: // maxResponseBodyBytes caps provider response reads to protect against runaway responses.
20: const maxResponseBodyBytes int64 = 10 * 1024 * 1024 // 10 MB
21: 
22: func readResponseBody(response *http.Response) ([]byte, error) {
23: 	defer response.Body.Close()
24: 	body, err := io.ReadAll(io.LimitReader(response.Body, maxResponseBodyBytes+1))
25: 	if err != nil {
26: 		return nil, err
27: 	}
28: 	if int64(len(body)) > maxResponseBodyBytes {
29: 		return nil, fmt.Errorf("response body exceeds %d bytes", maxResponseBodyBytes)
30: 	}
31: 	return body, nil
32: }
