  9: )
 10: 
 11: type ToolCallRuntime struct {
 12: 	provider       ToolCallProvider
 13: 	tools          DomainToolSet
 14: 	limits         LoopLimits
 15: 	contextPolicy  gitpkg.ContextPolicy
 16: 	repairPolicy   RepairPolicy
 17: 	readFiles      map[string]bool
 18: 	inspectedScope bool
 19: }
 20: 
 21: func NewToolCallRuntime(options ToolCallRuntimeOptions) *ToolCallRuntime {
 22: 	limits := options.Limits
 23: 	if limits.MaxToolCalls <= 0 {
 24: 		limits.MaxToolCalls = 32
 25: 	}
 26: 	if limits.MaxProviderRetries < 0 {
 27: 		limits.MaxProviderRetries = 0
 28: 	}
 29: 	contextPolicy := options.ContextPolicy
 30: 	if contextPolicy.Mode == "" {
 31: 		contextPolicy = gitpkg.ContextPolicy{Mode: gitpkg.ContextPolicyModeBounded, FileReadsAllowed: true}
 32: 	}
 33: 	return &ToolCallRuntime{
 34: 		provider:      options.Provider,
 35: 		tools:         options.Tools,
 36: 		limits:        limits,
 37: 		contextPolicy: contextPolicy,
 38: 		repairPolicy:  options.RepairPolicy,
 39: 		readFiles:     map[string]bool{},
 40: 	}
 41: }
 42: 
 43: func (r *ToolCallRuntime) Run() (RunResult, error) {
 44: 	if r.provider == nil {
 45: 		return RunResult{}, fmt.Errorf("tool call runtime requires a provider")
 46: 	}
 47: 
 48: 	var allResults []ToolCallResult
 49: 	var pendingResults []ToolCallResult
 50: 	toolCallCount := 0
 51: 	providerRetries := 0
 52: 	noToolStrikes := 0
 53: 	startedAt := time.Now()
 54: 	for {
 55: 		turn, err := r.provider.NextToolCalls(pendingResults)
 56: 		if err != nil {
 57: 			if providerRetries >= r.limits.MaxProviderRetries {
 58: 				return RunResult{Status: RunStatusLimited, Message: err.Error(), LimitReason: "max_provider_retries", Calls: allResults}, nil
 59: 			}
 60: 			providerRetries++
 61: 			continue
 62: 		}
 63: 		providerRetries = 0
 64: 		pendingResults = nil
 65: 		if len(turn.ToolCalls) == 0 {
 66: 			if noToolStrikes >= 4 {
 67: 				return RunResult{Status: RunStatusAborted, Message: "provider returned no tool calls", Calls: allResults}, nil
 68: 			}
 69: 			noToolStrikes++
 70: 			pendingResults = []ToolCallResult{{
 71: 				CallID: fmt.Sprintf("__reminder_%d", noToolStrikes),
 72: 				Name:   ToolName("__reminder__"),
 73: 				OK:     false,
 74: 				Error: &ToolCallError{
 75: 					Code:    "no_tool_call",
 76: 					Message: "Your last response had no tool call. You MUST respond by calling exactly one tool from: inspect_commit_scope, get_diff, read_file, preview_commit, create_commits, repair_file, finish, abort. Do not add commentary. Call create_commits now if you have enough information.",
 77: 				},
 78: 			}}
 79: 			continue
 80: 		}
 81: 		noToolStrikes = 0
 82: 		for _, call := range turn.ToolCalls {
 83: 			if r.durationExceeded(startedAt) {
 84: 				return RunResult{Status: RunStatusLimited, Message: "tool call duration limit exceeded", LimitReason: "max_duration", Calls: allResults}, nil
 85: 			}
 86: 			toolCallCount++
 87: 			if toolCallCount > r.limits.MaxToolCalls {
 88: 				return RunResult{Status: RunStatusLimited, Message: "tool call limit exceeded", LimitReason: "max_tool_calls", Calls: allResults}, nil
 89: 			}
 90: 			if call.Name == ToolFinish {
 91: 				return RunResult{Status: RunStatusCompleted, Message: stringArgument(call.Arguments, "message"), Calls: allResults}, nil
 92: 			}
 93: 			if call.Name == ToolAbort {
 94: 				return RunResult{Status: RunStatusAborted, Message: stringArgument(call.Arguments, "message"), Calls: allResults}, nil
 95: 			}
 96: 			result := r.executeToolCall(call)
 97: 			pendingResults = append(pendingResults, result)
 98: 			allResults = append(allResults, result)
 99: 			if r.durationExceeded(startedAt) {
100: 				return RunResult{Status: RunStatusLimited, Message: "tool call duration limit exceeded", LimitReason: "max_duration", Calls: allResults}, nil
101: 			}
102: 		}
103: 	}
104: }
105: 
106: func (r *ToolCallRuntime) durationExceeded(startedAt time.Time) bool {
107: 	return r.limits.MaxDuration > 0 && time.Since(startedAt) > r.limits.MaxDuration
108: }
109: 
110: func (r *ToolCallRuntime) executeToolCall(call ToolCallRequest) ToolCallResult {
111: 	if strings.TrimSpace(call.ID) == "" {
112: 		return invalidToolCall(call, "missing_call_id", "Tool call id is required.")
113: 	}
114: 	switch call.Name {
115: 	case ToolInspectCommitScope:
116: 		return r.executeInspectCommitScope(call)
117: 	case ToolGetDiff:
118: 		return r.executeGetDiff(call)
119: 	case ToolReadFile:
120: 		return r.executeReadFile(call)
121: 	case ToolPreviewCommit:
122: 		return r.executePreviewCommit(call)
123: 	case ToolCreateCommits:
124: 		return r.executeCreateCommits(call)
125: 	case ToolRepairFile:
126: 		return r.executeRepairFile(call)
127: 	default:
128: 		return invalidToolCall(call, "unknown_tool", fmt.Sprintf("Tool %q is not exposed by the runtime.", call.Name))
129: 	}
130: }
131: 
132: func (r *ToolCallRuntime) executeInspectCommitScope(call ToolCallRequest) ToolCallResult {
133: 	if r.tools.inspectCommitScope == nil {
134: 		return invalidToolCall(call, "tool_unavailable", "inspect_commit_scope is not available.")
135: 	}
136: 	scope, err := r.tools.inspectCommitScope()
137: 	if err != nil {
138: 		return toolFailed(call, err)
139: 	}
140: 	r.inspectedScope = true
141: 	return toolSucceeded(call, scope)
142: }
143: 
144: func (r *ToolCallRuntime) executeGetDiff(call ToolCallRequest) ToolCallResult {
145: 	if r.tools.getDiff == nil {
146: 		return invalidToolCall(call, "tool_unavailable", "get_diff is not available.")
147: 	}
148: 	diff, err := r.tools.getDiff()
149: 	if err != nil {
150: 		return toolFailed(call, err)
151: 	}
152: 	return toolSucceeded(call, diff)
153: }
154: 
155: func (r *ToolCallRuntime) executeReadFile(call ToolCallRequest) ToolCallResult {
156: 	if !r.contextPolicy.FileReadsAllowed {
157: 		return invalidToolCall(call, "context_policy_denied", "read_file is disabled by the active Context Policy.")
158: 	}
159: 	if r.tools.readFile == nil {
160: 		return invalidToolCall(call, "tool_unavailable", "read_file is not available.")
161: 	}
162: 	path := stringArgument(call.Arguments, "path")
163: 	if strings.TrimSpace(path) == "" {
164: 		return invalidToolCall(call, "invalid_arguments", "read_file requires a non-empty path.")
165: 	}
166: 	file, err := r.tools.readFile(path)
167: 	if err != nil {
168: 		return toolFailed(call, err)
169: 	}
170: 	r.readFiles[path] = true
171: 	return toolSucceeded(call, file)
172: }
173: 
174: func (r *ToolCallRuntime) executePreviewCommit(call ToolCallRequest) ToolCallResult {
175: 	if r.tools.previewCommit == nil {
176: 		return invalidToolCall(call, "tool_unavailable", "preview_commit is not available.")
177: 	}
178: 	message := stringArgument(call.Arguments, "message")
179: 	if strings.TrimSpace(message) == "" {
180: 		return invalidToolCall(call, "invalid_arguments", "preview_commit requires a non-empty message.")
181: 	}
182: 	preview, err := r.tools.previewCommit(CommitPreviewInput{Message: message})
183: 	if err != nil {
184: 		return toolFailed(call, err)
185: 	}
186: 	return toolSucceeded(call, preview)
187: }
188: 
189: func (r *ToolCallRuntime) executeCreateCommits(call ToolCallRequest) ToolCallResult {
190: 	if r.tools.createCommits == nil {
191: 		return invalidToolCall(call, "tool_unavailable", "create_commits is not available.")
192: 	}
193: 	if !r.inspectedScope {
194: 		return invalidToolCall(call, "inspect_before_create_required", "create_commits requires a successful inspect_commit_scope call first.")
195: 	}
196: 	input, err := createCommitsInputFromArguments(call.Arguments)
197: 	if err != nil {
198: 		return invalidToolCall(call, "invalid_arguments", err.Error())
199: 	}
200: 	created, err := r.tools.createCommits(input)
201: 	if err != nil {
202: 		return toolFailed(call, err)
203: 	}
204: 	return toolSucceeded(call, created)
205: }
206: 
207: func (r *ToolCallRuntime) executeRepairFile(call ToolCallRequest) ToolCallResult {
208: 	if r.tools.repairFile == nil {
209: 		return invalidToolCall(call, "tool_unavailable", "repair_file is not available.")
210: 	}
211: 	path := stringArgument(call.Arguments, "path")
212: 	if strings.TrimSpace(path) == "" {
213: 		return invalidToolCall(call, "invalid_arguments", "repair_file requires a non-empty path.")
214: 	}
215: 	content := stringArgument(call.Arguments, "content")
216: 	if strings.TrimSpace(content) == "" {
217: 		return invalidToolCall(call, "invalid_arguments", "repair_file requires non-empty content.")
218: 	}
219: 	if !r.readFiles[path] {
220: 		return invalidToolCall(call, "read_before_write_required", "repair_file requires a successful read_file call for the same path first.")
221: 	}
222: 	if !r.repairAllowed(path) {
223: 		return invalidToolCall(call, "repair_path_not_allowed", "repair_file can only write eligible conflicted files in Interactive Repair.")
224: 	}
225: 	confirmed, err := r.confirmRepairWrite(RepairFileInput{Path: path, Content: content})
226: 	if err != nil {
227: 		return toolFailed(call, err)
228: 	}
229: 	if !confirmed {
230: 		return invalidToolCall(call, "repair_confirmation_required", "repair_file requires developer confirmation before applying writes.")
231: 	}
232: 	repair, err := r.tools.repairFile(RepairFileInput{Path: path, Content: content})
233: 	if err != nil {
234: 		return toolFailed(call, err)
235: 	}
236: 	return toolSucceeded(call, repair)
237: }
238: 
239: func (r *ToolCallRuntime) confirmRepairWrite(input RepairFileInput) (bool, error) {
240: 	if r.repairPolicy.ConfirmWrite == nil {
241: 		return false, nil
242: 	}
243: 	return r.repairPolicy.ConfirmWrite(input)
244: }
245: 
246: func (r *ToolCallRuntime) repairAllowed(path string) bool {
247: 	if len(r.repairPolicy.AllowedPaths) == 0 {
248: 		return true
249: 	}
250: 	for _, allowed := range r.repairPolicy.AllowedPaths {
251: 		if allowed == path {
252: 			return true
253: 		}
254: 	}
255: 	return false
256: }
257: 
258: func toolSucceeded(call ToolCallRequest, result any) ToolCallResult {
259: 	return ToolCallResult{CallID: call.ID, Name: call.Name, OK: true, Result: result}
260: }
261: 
262: func toolFailed(call ToolCallRequest, err error) ToolCallResult {
263: 	return ToolCallResult{CallID: call.ID, Name: call.Name, OK: false, Error: &ToolCallError{Code: "tool_failed", Message: err.Error()}}
264: }
265: 
266: func invalidToolCall(call ToolCallRequest, code string, message string) ToolCallResult {
267: 	return ToolCallResult{
268: 		CallID: call.ID,
269: 		Name:   call.Name,
270: 		OK:     false,
271: 		Error:  &ToolCallError{Code: code, Message: message},
272: 	}
273: }
