286: func createCommitsInputFromArguments(arguments map[string]any) (CreateCommitsInput, error) {
287: 	if arguments == nil {
288: 		return CreateCommitsInput{}, fmt.Errorf("create_commits requires commits")
289: 	}
290: 	commitsValue, ok := arguments["commits"]
291: 	if !ok {
292: 		return CreateCommitsInput{}, fmt.Errorf("create_commits requires commits")
293: 	}
294: 	commitValues, ok := commitsValue.([]any)
295: 	if !ok {
296: 		return CreateCommitsInput{}, fmt.Errorf("create_commits commits must be an array")
297: 	}
298: 	if len(commitValues) == 0 {
299: 		return CreateCommitsInput{}, fmt.Errorf("create_commits requires at least one commit")
300: 	}
301: 	input := CreateCommitsInput{Kind: stringArgument(arguments, "kind")}
302: 	splitLimitations, err := createSplitLimitationsFromArguments(arguments)
303: 	if err != nil {
304: 		return CreateCommitsInput{}, err
305: 	}
306: 	input.SplitLimitations = splitLimitations
307: 	seen := map[string]bool{}
308: 	for _, rawCommit := range commitValues {
309: 		commitMap, ok := rawCommit.(map[string]any)
310: 		if !ok {
311: 			return CreateCommitsInput{}, fmt.Errorf("each commit must be an object")
312: 		}
313: 		message, _ := commitMap["message"].(string)
314: 		if strings.TrimSpace(message) == "" {
315: 			return CreateCommitsInput{}, fmt.Errorf("each commit requires a non-empty message")
316: 		}
317: 		files, err := stringArrayArgument(commitMap, "files")
318: 		if err != nil {
319: 			return CreateCommitsInput{}, err
320: 		}
321: 		if len(files) == 0 {
322: 			return CreateCommitsInput{}, fmt.Errorf("each commit requires at least one file")
323: 		}
324: 		for _, file := range files {
325: 			if strings.TrimSpace(file) == "" {
326: 				return CreateCommitsInput{}, fmt.Errorf("commit files must be non-empty paths")
327: 			}
328: 			if seen[file] {
329: 				return CreateCommitsInput{}, fmt.Errorf("commit plan assigns file more than once: %s", file)
330: 			}
331: 			seen[file] = true
332: 		}
333: 		input.Commits = append(input.Commits, CreateCommitInput{Message: message, Files: files})
334: 	}
335: 	return input, nil
336: }
337: 
338: func createSplitLimitationsFromArguments(arguments map[string]any) ([]CreateSplitLimitation, error) {
339: 	value, ok := arguments["splitLimitations"]
340: 	if !ok {
341: 		return nil, nil
342: 	}
343: 	items, ok := value.([]any)
344: 	if !ok {
345: 		return nil, fmt.Errorf("splitLimitations must be an array")
346: 	}
347: 	limitations := make([]CreateSplitLimitation, 0, len(items))
348: 	for _, item := range items {
349: 		object, ok := item.(map[string]any)
350: 		if !ok {
351: 			return nil, fmt.Errorf("each split limitation must be an object")
352: 		}
353: 		limitations = append(limitations, CreateSplitLimitation{Code: stringMapArgument(object, "code"), Message: stringMapArgument(object, "message"), Fallback: stringMapArgument(object, "fallback")})
354: 	}
355: 	return limitations, nil
356: }
357: 
358: func stringMapArgument(arguments map[string]any, key string) string {
359: 	value, ok := arguments[key].(string)
360: 	if !ok {
361: 		return ""
362: 	}
363: 	return value
364: }
365: 
366: func stringArrayArgument(arguments map[string]any, key string) ([]string, error) {
367: 	value, ok := arguments[key]
368: 	if !ok {
369: 		return nil, fmt.Errorf("each commit requires files")
370: 	}
371: 	switch typed := value.(type) {
372: 	case []any:
373: 		result := make([]string, 0, len(typed))
374: 		for _, item := range typed {
375: 			text, ok := item.(string)
376: 			if !ok {
377: 				return nil, fmt.Errorf("commit files must be strings")
378: 			}
379: 			result = append(result, text)
380: 		}
381: 		return result, nil
382: 	case []string:
383: 		return append([]string{}, typed...), nil
384: 	default:
385: 		return nil, fmt.Errorf("commit files must be an array")
386: 	}
387: }

