 64: func executeWithRuntime(args []string, runtime Runtime) int {
 65: 	if len(args) == 0 {
 66: 		return runRoot(nil, runtime)
 67: 	}
 68: 
 69: 	for _, arg := range args {
 70: 		if arg == "--json" {
 71: 			continue
 72: 		}
 73: 		if arg == "--help" || arg == "-h" {
 74: 			if hasJSONFlag(args) {
 75: 				fmt.Fprintln(runtime.Stderr, "error: --json cannot be combined with --help.")
 76: 				return int(output.Error)
 77: 			}
 78: 			printUsage(runtime.Stdout)
 79: 			return int(output.Success)
 80: 		}
 81: 		if arg == "--version" || arg == "-version" {
 82: 			fmt.Fprintln(runtime.Stdout, version)
 83: 			return int(output.Success)
 84: 		}
 85: 		break
 86: 	}
 87: 
 88: 	command, commandIndex := resolveCommand(args)
 89: 	switch command {
 90: 	case "":
 91: 		return runRoot(args, runtime)
 92: 	case "auto":
 93: 		return runAuto(args[commandIndex+1:], runtime)
 94: 	case "init":
 95: 		return commands.RunInit(args[commandIndex+1:], commands.InitRuntime{
 96: 			CWD:              runtime.CWD,
 97: 			Env:              runtime.Env,
 98: 			Stdin:            runtime.Stdin,
 99: 			Stdout:           runtime.Stdout,
100: 			Stderr:           runtime.Stderr,
101: 			IsTTY:            runtime.IsTTY,
102: 			SecretStore:      runtime.SecretStore,
103: 			OnboardingRunner: runtimeOnboardingRunner(runtime),
104: 		})
105: 	case "config":
106: 		return runConfigCommand(args[commandIndex+1:], runtime)
107: 	case "doctor":
108: 		return commands.RunDoctor(args[commandIndex+1:], commands.DoctorRuntime{
109: 			CWD:         runtime.CWD,
110: 			Env:         runtime.Env,
111: 			Stdout:      runtime.Stdout,
112: 			Stderr:      runtime.Stderr,
113: 			IsTTY:       runtime.IsTTY,
114: 			SecretStore: runtime.SecretStore,
115: 			RenderRich:  doctorRichRenderer(),
116: 		})
117: 	case "split", "repair", "check", "onboard":
118: 		fmt.Fprintf(runtime.Stderr, "error: removed command '%s'\n", command)
119: 		fmt.Fprintln(runtime.Stderr, "Use `cnm` for Interactive Commit or `cnm auto` for Autonomous Commit.")
120: 		return int(output.Error)
121: 	case "help":
122: 		printUsage(runtime.Stdout)
123: 		return int(output.Success)
124: 	default:
125: 		fmt.Fprintf(runtime.Stderr, "error: unknown command '%s'\n", command)
126: 		fmt.Fprintln(runtime.Stderr, "Run cnm --help to inspect available commands.")
127: 		return int(output.Error)
128: 	}
129: }
