131: type debugCommandFinishedEvent struct {
132: 	SchemaVersion int    `json:"schemaVersion"`
133: 	Event         string `json:"event"`
134: 	Command       string `json:"command"`
135: 	ExitCode      int    `json:"exitCode"`
136: 	Timestamp     string `json:"timestamp"`
