317: func runtimeOnboardingRunner(runtime Runtime) commands.OnboardingRunnerFunc {
318: 	if !runtime.IsTTY {
319: 		return nil
320: 	}
321: 	if runtime.OnboardingRunner == nil {
322: 		return nil
323: 	}
324: 	return func(prefill commands.OnboardingPrefill) (commands.OnboardingAnswers, error) {
325: 		input := tui.OnboardingInput{
326: 			CurrentProvider: prefill.Provider,
327: 			CurrentModel:    prefill.Model,
328: 			CurrentBaseURL:  prefill.BaseURL,
329: 			CurrentStyle:    prefill.PromptStyle,
330: 			CurrentLanguage: prefill.MessageLanguage,
331: 			CurrentStanding: prefill.StandingInstruction,
332: 		}
333: 		result, err := runtime.OnboardingRunner(input, tui.Runtime{Input: runtime.Stdin, Output: runtime.Stdout})
334: 		if err != nil {
335: 			return commands.OnboardingAnswers{}, err
336: 		}
337: 		return commands.OnboardingAnswers{
338: 			Cancelled:           result.Cancelled,
339: 			Provider:            result.Provider,
340: 			Model:               result.Model,
341: 			BaseURL:             result.BaseURL,
342: 			PromptStyle:         result.PromptStyle,
343: 			MessageLanguage:     result.MessageLanguage,
344: 			StandingInstruction: result.StandingInstruction,
345: 			APIKey:              result.APIKey,
346: 		}, nil
347: 	}
348: }
