350: func runConfigPanel(runtime Runtime) int {
351: 	resolved, err := config.ResolveEffectiveConfig(config.ResolveConfigOptions{
352: 		CWD:         runtime.CWD,
353: 		Env:         runtime.Env,
354: 		SecretStore: runtime.SecretStore,
355: 	})
356: 	if err != nil {
357: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
358: 		return int(output.Error)
359: 	}
360: 	for _, warning := range resolved.Warnings {
361: 		fmt.Fprintln(runtime.Stderr, "Warning: "+warning)
362: 	}
363: 	paths := config.GetConfigPaths(config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
364: 	sources := config.SummarizeConfigSources(resolved)
365: 	input := tui.ConfigPanelInput{
366: 		Effective: resolved.Values,
367: 		Sources:   sources,
368: 		UserPath:  paths.UserConfigPath,
369: 		WriteValue: func(key config.ConfigKey, value string) error {
370: 			patch, err := config.ParseKeyValue(string(key), value)
371: 			if err != nil {
372: 				return err
373: 			}
374: 			if key == config.ConfigKeyAPIKey && runtime.SecretStore != nil {
375: 				provider, err := currentConfigPanelProvider(runtime)
376: 				if err != nil {
377: 					return err
378: 				}
379: 				if patch.APIKey != nil {
380: 					if err := runtime.SecretStore.SetAPIKey(provider, *patch.APIKey); err != nil {
381: 						return err
382: 					}
383: 				}
384: 				return nil
385: 			}
386: 			_, err = config.WriteUserConfigPatch(patch, config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
387: 			return err
388: 		},
389: 		UnsetValue: func(key config.ConfigKey) error {
390: 			_, err := config.UnsetUserConfigKey(key, config.ConfigEnvironment{CWD: runtime.CWD, Env: runtime.Env})
391: 			return err
392: 		},
393: 		Reload: func() (config.EffectiveConfig, config.ConfigSourceSummary, error) {
394: 			next, err := config.ResolveEffectiveConfig(config.ResolveConfigOptions{
395: 				CWD:         runtime.CWD,
396: 				Env:         runtime.Env,
397: 				SecretStore: runtime.SecretStore,
398: 			})
399: 			if err != nil {
400: 				return config.EffectiveConfig{}, config.ConfigSourceSummary{}, err

