278: func buildDoctorView(report doctor.Report) tui.DoctorView {
279: 	view := tui.DoctorView{
280: 		Status:            report.Status,
281: 		Errors:            report.Summary.Errors,
282: 		Warnings:          report.Summary.Warnings,
283: 		OK:                report.OK,
284: 		GitMessage:        report.Checks.Git.Message,
285: 		GitStatus:         string(report.Checks.Git.Status),
286: 		RepoMessage:       report.Checks.Repository.Message,
287: 		RepoStatus:        string(report.Checks.Repository.Status),
288: 		ConfigMessage:     report.Checks.EffectiveConfig.Message,
289: 		ConfigStatus:      string(report.Checks.EffectiveConfig.Status),
290: 		CapabilityMessage: report.Checks.ProviderCapability.Message,
291: 		CapabilityStatus:  string(report.Checks.ProviderCapability.Status),
292: 		ProviderName:      report.Checks.EffectiveConfig.Config.Provider,
293: 		ModelName:         report.Checks.EffectiveConfig.Config.Model,
294: 		APIKeySource:      report.Checks.EffectiveConfig.Sources.APIKey,
295: 		UserConfig:        report.Paths.UserConfigPath,
296: 		ProjectConfig:     report.Paths.ProjectConfigPath,
297: 	}
298: 	if report.Probe != nil {
299: 		view.ProbeAttempted = true
300: 		view.ProbeStatus = report.Probe.Status
301: 		if report.Probe.Message != "" {
302: 			view.ProbeMessage = report.Probe.Message
303: 		} else if report.Probe.Error != "" {
304: 			view.ProbeMessage = report.Probe.Error
305: 		}
306: 	}
307: 	for _, issue := range report.Issues {
308: 		view.Issues = append(view.Issues, tui.DoctorIssue{
309: 			Severity: string(issue.Severity),
310: 			Check:    issue.Check,
311: 			Message:  issue.Message,
312: 		})
313: 	}
314: 	return view
315: }
