139: func writeDebugCommandFinished(runtime Runtime, args []string, exitCode int) {
140: 	path := strings.TrimSpace(runtimeEnvValue(runtime.Env, "CNM_DEBUG_LOG"))
141: 	if path == "" {
142: 		return
143: 	}
144: 	if !filepath.IsAbs(path) {
145: 		path = filepath.Join(runtime.CWD, path)
146: 	}
147: 	if dir := filepath.Dir(path); dir != "." && strings.TrimSpace(dir) != "" {
148: 		if err := os.MkdirAll(dir, 0o755); err != nil {
149: 			return
150: 		}
151: 	}
152: 	file, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
153: 	if err != nil {
154: 		return
155: 	}
156: 	defer file.Close()
157: 	_ = json.NewEncoder(file).Encode(debugCommandFinishedEvent{
158: 		SchemaVersion: 1,
159: 		Event:         "command_finished",
160: 		Command:       debugCommandName(args),
161: 		ExitCode:      exitCode,
162: 		Timestamp:     time.Now().UTC().Format(time.RFC3339),
163: 	})
164: }
