235: func (p *httpToolCallProvider) newRequest(payload map[string]any) (*http.Request, error) {
236: 	body, err := json.Marshal(payload)
237: 	if err != nil {
238: 		return nil, err
239: 	}
240: 	endpoint := p.endpoint()
241: 	request, err := newJSONRequest(http.MethodPost, endpoint, body)
242: 	if err != nil {
243: 		return nil, err
244: 	}
245: 	switch p.cfg.Provider {
246: 	case config.ProviderOpenAIResponses, config.ProviderOpenAICompatible:
247: 		request.Header.Set("Authorization", "Bearer "+*p.cfg.APIKey)
248: 	case config.ProviderAnthropic:
249: 		request.Header.Set("x-api-key", *p.cfg.APIKey)
250: 		request.Header.Set("anthropic-version", "2023-06-01")
251: 	}
252: 	applyUserAgent(request, p.cfg)
253: 	return request, nil
254: }
255: 
256: func (p *httpToolCallProvider) endpoint() string {
257: 	switch p.cfg.Provider {
258: 	case config.ProviderOpenAICompatible:
259: 		return joinURL(*p.cfg.BaseURL, "/chat/completions")
260: 	case config.ProviderOpenAIResponses:
261: 		return joinURL(optionalStringOrDefault(p.cfg.BaseURL, defaultOpenAIBaseURL), "/responses")
262: 	case config.ProviderAnthropic:
263: 		return joinURL(optionalStringOrDefault(p.cfg.BaseURL, defaultAnthropicBaseURL), "/messages")
264: 	case config.ProviderGoogleGemini:
265: 		baseURL := optionalStringOrDefault(p.cfg.BaseURL, defaultGeminiBaseURL)
266: 		return joinURL(baseURL, "/v1beta/models/"+url.PathEscape(p.cfg.Model)+":generateContent") + "?key=" + url.QueryEscape(*p.cfg.APIKey)
267: 	default:
268: 		return ""
269: 	}
270: }
