272: func (p *httpToolCallProvider) captureProviderState(body []byte) {
273: 	switch p.cfg.Provider {
274: 	case config.ProviderOpenAIResponses:
275: 		p.captureOpenAIResponsesID(body)
276: 	case config.ProviderOpenAICompatible:
277: 		p.captureOpenAICompatibleAssistant(body)
278: 	case config.ProviderAnthropic:
279: 		p.captureAnthropicAssistant(body)
280: 	case config.ProviderGoogleGemini:
281: 		p.captureGeminiModelContent(body)
282: 	}
283: }
284: 
285: func (p *httpToolCallProvider) captureOpenAIResponsesID(body []byte) {
286: 	var response struct {
287: 		ID     string           `json:"id"`
288: 		Output []map[string]any `json:"output"`
289: 	}
290: 	if err := json.Unmarshal(body, &response); err != nil {
291: 		return
292: 	}
293: 	if strings.TrimSpace(response.ID) != "" {
294: 		p.previousResponseID = response.ID
295: 	}
296: 	for _, item := range response.Output {
297: 		t, _ := item["type"].(string)
298: 		if t == "function_call" || t == "message" || t == "reasoning" {
299: 			p.responsesInput = append(p.responsesInput, item)
300: 		}
301: 	}
302: }
303: 
304: func (p *httpToolCallProvider) captureOpenAICompatibleAssistant(body []byte) {
305: 	var response struct {
306: 		Choices []struct {
307: 			Message map[string]any `json:"message"`
308: 		} `json:"choices"`
309: 	}
310: 	if err := json.Unmarshal(body, &response); err != nil || len(response.Choices) == 0 || len(response.Choices[0].Message) == 0 {
311: 		return
312: 	}
313: 	p.chatMessages = append(p.chatMessages, response.Choices[0].Message)
314: }
315: 
316: func (p *httpToolCallProvider) captureAnthropicAssistant(body []byte) {
317: 	var response struct {
318: 		Content []map[string]any `json:"content"`
319: 	}
320: 	if err := json.Unmarshal(body, &response); err != nil || len(response.Content) == 0 {
321: 		return
322: 	}
323: 	p.anthropicMessages = append(p.anthropicMessages, map[string]any{"role": "assistant", "content": response.Content})
324: }
325: 
326: func (p *httpToolCallProvider) captureGeminiModelContent(body []byte) {
327: 	var response struct {
328: 		Candidates []struct {
329: 			Content map[string]any `json:"content"`
330: 		} `json:"candidates"`
331: 	}
332: 	if err := json.Unmarshal(body, &response); err != nil || len(response.Candidates) == 0 || len(response.Candidates[0].Content) == 0 {
333: 		return
334: 	}
335: 	content := response.Candidates[0].Content
336: 	if _, ok := content["role"]; !ok {
337: 		content["role"] = "model"
338: 	}
339: 	p.geminiContents = append(p.geminiContents, content)
340: }
341: 
342: func normalizeToolMessages(values []any) []map[string]any {
343: 	messages := make([]map[string]any, 0, len(values))
344: 	for _, value := range values {
345: 		message, ok := value.(map[string]any)
346: 		if ok {
347: 			messages = append(messages, message)
348: 		}
349: 	}
350: 	return messages
351: }

