 54: func (p *httpToolCallProvider) NextToolCalls(results []runtimex.ToolCallResult) (runtimex.ProviderTurn, error) {
 55: 	payload, err := p.requestPayload(results)
 56: 	if err != nil {
 57: 		return runtimex.ProviderTurn{}, err
 58: 	}
 59: 	request, err := p.newRequest(payload)
 60: 	if err != nil {
 61: 		return runtimex.ProviderTurn{}, err
 62: 	}
 63: 	response, err := p.client.Do(request)
 64: 	if err != nil {
 65: 		return runtimex.ProviderTurn{}, err
 66: 	}
 67: 	body, err := readResponseBody(response)
 68: 	if err != nil {
 69: 		return runtimex.ProviderTurn{}, err
 70: 	}
 71: 	if response.StatusCode < 200 || response.StatusCode >= 300 {
 72: 		return runtimex.ProviderTurn{}, fmt.Errorf("provider request failed with http %d", response.StatusCode)
 73: 	}
 74: 	p.captureProviderState(body)
 75: 	p.turnCount++
 76: 	turn, err := p.adapter.ParseTurn(body)
 77: 	if err != nil {
 78: 		return runtimex.ProviderTurn{}, fmt.Errorf("provider response parse error: %w", err)
 79: 	}
 80: 	return turn, nil
 81: }
