102: func (p *httpToolCallProvider) reminderPayload(reminder runtimex.ToolCallResult) (map[string]any, error) {
103: 	message := "Reminder: please call one of the available tools to continue."
104: 	if reminder.Error != nil && reminder.Error.Message != "" {
105: 		message = reminder.Error.Message
106: 	}
107: 	payload := map[string]any{}
108: 	fragment, err := p.adapter.BuildInitialRequest(p.tools)
109: 	if err == nil {
110: 		var toolsPayload map[string]any
111: 		if err := json.Unmarshal(fragment, &toolsPayload); err == nil {
112: 			if t, ok := toolsPayload["tools"]; ok {
113: 				payload["tools"] = t
114: 			}
115: 		}
116: 	}
117: 	switch p.cfg.Provider {
118: 	case config.ProviderOpenAIResponses:
119: 		payload["model"] = p.cfg.Model
120: 		payload["instructions"] = p.instructions
121: 		p.responsesInput = append(p.responsesInput, map[string]any{"role": "user", "content": message})
122: 		payload["input"] = p.responsesInput
123: 		payload["max_output_tokens"] = resolveMaxOutputTokens(p.cfg)
124: 		payload["tool_choice"] = "auto"
125: 	case config.ProviderOpenAICompatible:
126: 		payload["model"] = p.cfg.Model
127: 		p.chatMessages = append(p.chatMessages, map[string]any{"role": "user", "content": message})
128: 		payload["messages"] = p.chatMessages
129: 		payload["temperature"] = 0.2
130: 		payload["max_tokens"] = resolveMaxOutputTokens(p.cfg)
131: 		payload["tool_choice"] = "required"
132: 	case config.ProviderAnthropic:
133: 		payload["model"] = p.cfg.Model
134: 		payload["system"] = p.instructions
135: 		payload["max_tokens"] = resolveMaxOutputTokens(p.cfg)
136: 		p.anthropicMessages = append(p.anthropicMessages, map[string]any{"role": "user", "content": message})
137: 		payload["messages"] = p.anthropicMessages
138: 		payload["tool_choice"] = map[string]any{"type": "any"}
139: 	case config.ProviderGoogleGemini:
140: 		p.geminiContents = append(p.geminiContents, map[string]any{"role": "user", "parts": []map[string]string{{"text": message}}})
141: 		payload["contents"] = p.geminiContents
142: 		payload["generationConfig"] = map[string]any{"temperature": 0.2, "maxOutputTokens": resolveMaxOutputTokens(p.cfg)}
143: 	}
144: 	return payload, nil
145: }
