 83: func (p *httpToolCallProvider) requestPayload(results []runtimex.ToolCallResult) (map[string]any, error) {
 84: 	if p.turnCount == 0 && len(results) == 0 {
 85: 		return p.initialPayload()
 86: 	}
 87: 	if len(results) == 1 && results[0].Name == runtimex.ToolName("__reminder__") {
 88: 		return p.reminderPayload(results[0])
 89: 	}
 90: 	fragment, err := p.adapter.BuildToolResultPayload(results)
 91: 	if err != nil {
 92: 		return nil, err
 93: 	}
 94: 	var payload map[string]any
 95: 	if err := json.Unmarshal(fragment, &payload); err != nil {
 96: 		return nil, err
 97: 	}
 98: 	p.applyContinuationPayload(payload)
 99: 	return payload, nil
100: }
