188: func (p *httpToolCallProvider) applyContinuationPayload(payload map[string]any) {
189: 	if payload["tools"] == nil {
190: 		fragment, err := p.adapter.BuildInitialRequest(p.tools)
191: 		if err == nil {
192: 			var toolsPayload map[string]any
193: 			if err := json.Unmarshal(fragment, &toolsPayload); err == nil {
194: 				if t, ok := toolsPayload["tools"]; ok {
195: 					payload["tools"] = t
196: 				}
197: 			}
198: 		}
199: 	}
200: 	switch p.cfg.Provider {
201: 	case config.ProviderOpenAIResponses:
202: 		payload["model"] = p.cfg.Model
203: 		payload["instructions"] = p.instructions
204: 		newInputs, _ := payload["input"].([]any)
205: 		for _, item := range newInputs {
206: 			if m, ok := item.(map[string]any); ok {
207: 				p.responsesInput = append(p.responsesInput, m)
208: 			}
209: 		}
210: 		payload["input"] = p.responsesInput
211: 		payload["max_output_tokens"] = resolveMaxOutputTokens(p.cfg)
212: 		payload["tool_choice"] = "auto"
213: 	case config.ProviderOpenAICompatible:
214: 		payload["model"] = p.cfg.Model
215: 		toolMessages, _ := payload["messages"].([]any)
216: 		p.chatMessages = append(p.chatMessages, normalizeToolMessages(toolMessages)...)
217: 		payload["messages"] = p.chatMessages
218: 		payload["tool_choice"] = "required"
219: 	case config.ProviderAnthropic:
220: 		payload["model"] = p.cfg.Model
221: 		payload["system"] = p.instructions
222: 		payload["max_tokens"] = resolveMaxOutputTokens(p.cfg)
223: 		toolMessages, _ := payload["messages"].([]any)
224: 		p.anthropicMessages = append(p.anthropicMessages, normalizeToolMessages(toolMessages)...)
225: 		payload["messages"] = p.anthropicMessages
226: 		payload["tool_choice"] = map[string]any{"type": "any"}
227: 	case config.ProviderGoogleGemini:
228: 		contents, _ := payload["contents"].([]any)
229: 		p.geminiContents = append(p.geminiContents, normalizeToolMessages(contents)...)
230: 		payload["contents"] = p.geminiContents
231: 		payload["generationConfig"] = map[string]any{"temperature": 0.2, "maxOutputTokens": resolveMaxOutputTokens(p.cfg)}
232: 	}
233: }
