256: func (p *httpToolCallProvider) endpoint() string {
257: 	switch p.cfg.Provider {
258: 	case config.ProviderOpenAICompatible:
259: 		return joinURL(*p.cfg.BaseURL, "/chat/completions")
260: 	case config.ProviderOpenAIResponses:
261: 		return joinURL(optionalStringOrDefault(p.cfg.BaseURL, defaultOpenAIBaseURL), "/responses")
262: 	case config.ProviderAnthropic:
263: 		return joinURL(optionalStringOrDefault(p.cfg.BaseURL, defaultAnthropicBaseURL), "/messages")
264: 	case config.ProviderGoogleGemini:
265: 		baseURL := optionalStringOrDefault(p.cfg.BaseURL, defaultGeminiBaseURL)
266: 		return joinURL(baseURL, "/v1beta/models/"+url.PathEscape(p.cfg.Model)+":generateContent") + "?key=" + url.QueryEscape(*p.cfg.APIKey)
267: 	default:
268: 		return ""
269: 	}
270: }
