326: func (p *httpToolCallProvider) captureGeminiModelContent(body []byte) {
327: 	var response struct {
328: 		Candidates []struct {
329: 			Content map[string]any `json:"content"`
330: 		} `json:"candidates"`
331: 	}
332: 	if err := json.Unmarshal(body, &response); err != nil || len(response.Candidates) == 0 || len(response.Candidates[0].Content) == 0 {
333: 		return
334: 	}
335: 	content := response.Candidates[0].Content
336: 	if _, ok := content["role"]; !ok {
337: 		content["role"] = "model"
338: 	}
339: 	p.geminiContents = append(p.geminiContents, content)
340: }
