342: func normalizeToolMessages(values []any) []map[string]any {
343: 	messages := make([]map[string]any, 0, len(values))
344: 	for _, value := range values {
345: 		message, ok := value.(map[string]any)
346: 		if ok {
347: 			messages = append(messages, message)
348: 		}
349: 	}
350: 	return messages
351: }

