436: func runAuto(args []string, runtime Runtime) int {
437: 	parsed, err := parseAutoArgs(args)
438: 	if err != nil {
439: 		if errors.Is(err, errAutoHelp) {
440: 			printAutoUsage(runtime.Stdout)
441: 			return int(output.Success)
442: 		}
443: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
444: 		return int(output.UsageError)
445: 	}
446: 
447: 	resolvedConfig, configErr := config.ResolveEffectiveConfig(config.ResolveConfigOptions{CWD: runtime.CWD, Env: runtime.Env, SecretStore: runtime.SecretStore})
448: 	preferenceSources := gitpkg.PreferenceExposure{}
449: 	if configErr == nil {
450: 		sourceSummary := config.SummarizeConfigSources(resolvedConfig)
451: 		preferenceSources = gitpkg.PreferenceExposure{
452: 			Provider:            string(sourceSummary.Provider),
453: 			Model:               string(sourceSummary.Model),
454: 			APIKey:              string(sourceSummary.APIKey),
455: 			PromptStyle:         string(sourceSummary.PromptStyle),
456: 			MessageLanguage:     string(sourceSummary.MessageLanguage),
457: 			StandingInstruction: sourceSummary.StandingInstruction,
458: 		}
459: 	}
460: 
461: 	scope, scopeErr := gitpkg.InspectCommitScope(gitpkg.CommitScopeOptions{
462: 		CWD:               runtime.CWD,
463: 		Env:               runtime.Env,
464: 		StagedOnly:        parsed.Staged,
465: 		IncludeUntracked:  !parsed.NoUntracked,
466: 		DiffOnly:          parsed.DiffOnly,
467: 		PreferenceSources: preferenceSources,
468: 		Pathspecs:         parsed.Pathspecs,
469: 	})
470: 
471: 	if scopeErr != nil {
472: 		if parsed.JSON {
473: 			router := output.NewRouter(true, runtime.Stdout, runtime.Stderr)
474: 			_ = router.WriteJSON(map[string]any{
475: 				"schemaVersion": 1,
476: 				"command":       "cnm auto",
477: 				"ok":            false,
478: 				"status":        "scope_error",
479: 				"scopeError":    scopeErr.Error(),
480: 			})
481: 		} else {
482: 			fmt.Fprintln(runtime.Stderr, scopeErr.Error())
483: 		}
484: 		return int(output.Error)
485: 	}
486: 	if !scope.HasSelectedChanges {
487: 		if parsed.JSON {
488: 			router := output.NewRouter(true, runtime.Stdout, runtime.Stderr)
489: 			_ = router.WriteJSON(map[string]any{
490: 				"schemaVersion": 1,
491: 				"command":       "cnm auto",
492: 				"ok":            true,
493: 				"status":        "no_changes",
494: 				"scope":         scope,
495: 				"contextPolicy": scope.ContextPolicy,
496: 				"aiExposure":    scope.AIExposure,
497: 			})
498: 		} else {
499: 			fmt.Fprintln(runtime.Stdout, "No selected changes.")
500: 		}
501: 		return int(output.Success)
502: 	}
503: 	if scopeHasConflict(scope) {
504: 		message := "Conflicts are present; cnm auto cannot repair or commit conflicts non-interactively."
505: 		if parsed.TUI {
506: 			if issue := autoConfigIssueFromResolved(configErr, resolvedConfig.Values); issue != nil {
507: 				return writeAutoConfigMissing(runtime, parsed, scope, *issue)
508: 			}
509: 			return runConflictTUIHandoff(runtime, scope, parsed, resolvedConfig.Values, message)
510: 		}
511: 		if parsed.JSON {
512: 			router := output.NewRouter(true, runtime.Stdout, runtime.Stderr)
513: 			_ = router.WriteJSON(map[string]any{
514: 				"schemaVersion": 1,
515: 				"command":       "cnm auto",
516: 				"ok":            false,
517: 				"status":        "conflict",
518: 				"error":         message,
519: 				"scope":         scope,
520: 				"contextPolicy": scope.ContextPolicy,
521: 				"aiExposure":    scope.AIExposure,
522: 			})
523: 		} else {
524: 			fmt.Fprintln(runtime.Stderr, message)
525: 		}
526: 		return int(output.Error)
527: 	}
528: 	if len(scope.SecretBlockers) > 0 {
529: 		if parsed.JSON {
530: 			router := output.NewRouter(true, runtime.Stdout, runtime.Stderr)
531: 			_ = router.WriteJSON(map[string]any{
532: 				"schemaVersion":  1,
533: 				"command":        "cnm auto",
534: 				"ok":             false,
535: 				"status":         "secret_blocked",
536: 				"scope":          scope,
537: 				"contextPolicy":  scope.ContextPolicy,
538: 				"aiExposure":     scope.AIExposure,
539: 				"secretBlockers": scope.SecretBlockers,
540: 			})
541: 		} else {
542: 			fmt.Fprintln(runtime.Stderr, "Secret Blocker: selected changes contain potential secrets.")
543: 		}
544: 		return int(output.Error)
545: 	}
546: 	if issue := autoConfigIssueFromResolved(configErr, resolvedConfig.Values); issue != nil {
547: 		return writeAutoConfigMissing(runtime, parsed, scope, *issue)
548: 	}
549: 	if parsed.DryRun {
550: 		execution, err := executeAutoCommit(runtime, scope, parsed, resolvedConfig.Values)
551: 		if err != nil {
552: 			fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
553: 			return int(output.Error)
554: 		}
555: 		commitPlan := execution.Plan
556: 		if parsed.JSON {
557: 			router := output.NewRouter(true, runtime.Stdout, runtime.Stderr)
558: 			_ = router.WriteJSON(map[string]any{
559: 				"schemaVersion": 1,
560: 				"command":       "cnm auto",
561: 				"ok":            true,
562: 				"status":        "plan_preview",
563: 				"dryRun":        true,
564: 				"scope":         scope,
565: 				"contextPolicy": scope.ContextPolicy,
566: 				"aiExposure":    scope.AIExposure,
567: 				"commitPlan":    commitPlan,
568: 			})
569: 		} else {
570: 			fmt.Fprintf(runtime.Stdout, "Plan: %s\n", commitPlan.Commits[0].Message)
571: 		}
572: 		return int(output.Success)
573: 	}
574: 
575: 	if !parsed.DryRun && scope.HasSelectedChanges && len(scope.SecretBlockers) == 0 {
576: 		execution, err := executeAutoCommit(runtime, scope, parsed, resolvedConfig.Values)
577: 		if err != nil {
578: 			fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
579: 			return int(output.Error)
580: 		}
581: 		commitPlan := execution.Plan
582: 		commitResult := execution.lastResult()
583: 		if commitResult.Git.ExitCode != 0 {
584: 			if parsed.JSON {
585: 				router := output.NewRouter(true, runtime.Stdout, runtime.Stderr)
586: 				_ = router.WriteJSON(map[string]any{
587: 					"schemaVersion": 1,
588: 					"command":       "cnm auto",
589: 					"ok":            false,
590: 					"status":        "commit_failed",
591: 					"error":         firstNonEmptyString(commitResult.Git.Stderr, commitResult.Git.Stdout, "git commit failed"),
592: 					"scope":         scope,
593: 					"contextPolicy": scope.ContextPolicy,
594: 					"aiExposure":    scope.AIExposure,
595: 					"commitPlan":    commitPlan,
596: 					"transaction":   execution.Transaction,
597: 				})
598: 			} else {
599: 				fmt.Fprintln(runtime.Stderr, firstNonEmptyString(commitResult.Git.Stderr, commitResult.Git.Stdout, "git commit failed"))
600: 			}
601: 			return int(output.Error)
602: 		}
603: 		if parsed.JSON {
604: 			router := output.NewRouter(true, runtime.Stdout, runtime.Stderr)
605: 			commits := execution.commitSummaries()
606: 			_ = router.WriteJSON(map[string]any{
607: 				"schemaVersion": 1,
608: 				"command":       "cnm auto",
609: 				"ok":            true,
610: 				"status":        "committed",
611: 				"dryRun":        false,
612: 				"scope":         scope,
613: 				"contextPolicy": scope.ContextPolicy,
614: 				"aiExposure":    scope.AIExposure,
615: 				"commitPlan":    commitPlan,
616: 				"commit": map[string]any{
617: 					"hash":    commitResult.Hash,
618: 					"message": commitResult.Message,
619: 				},
620: 				"commits": commits,
621: 				"messageRetry": map[string]any{
622: 					"attempted": execution.RetryAttempt,
623: 					"count":     execution.RetryCount,
624: 				},
625: 			})
626: 		} else {
627: 			fmt.Fprintf(runtime.Stdout, "Committed %s %s\n", commitResult.Hash, commitResult.Message)
628: 		}
629: 		return int(output.Success)
630: 	}
631: 
632: 	fmt.Fprintln(runtime.Stderr, "error: invalid Autonomous Commit state")
633: 	return int(output.Error)
634: }
