641: func autoRequiredConfigIssue(values config.EffectiveConfig) *autoConfigIssue {
642: 	if values.APIKey == nil || strings.TrimSpace(*values.APIKey) == "" {
643: 		return &autoConfigIssue{Code: "api_key_missing", Message: "No API key is configured. Run `cnm init` to save one in Secret Store, or set CNM_API_KEY for this process."}
644: 	}
645: 	if strings.TrimSpace(values.Model) == "" {
646: 		return &autoConfigIssue{Code: "model_missing", Message: "No model is configured. Run `cnm init` or `cnm config set model <model>` before using cnm auto."}
