675: func runConflictTUIHandoff(runtime Runtime, scope gitpkg.CommitScope, parsed autoArgs, resolvedConfig config.EffectiveConfig, message string) int {
676: 	tuiRunner := runtime.TUIRunner
677: 	if tuiRunner == nil {
678: 		tuiRunner = tui.Run
679: 	}
680: 	result, err := tuiRunner(tui.ModelInput{
681: 		RepairContext: &tui.RepairContext{Reason: message, EligibleFiles: conflictFilePaths(scope)},
682: 		Scope:         scope,
683: 		FileReader:    repairFileReader(runtime),
684: 	}, tui.Runtime{Input: runtime.Stdin, Output: runtime.Stdout})
685: 	if err != nil {
686: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
687: 		return int(output.Error)
688: 	}
689: 	if !result.Accepted || result.Cancelled {
690: 		fmt.Fprintln(runtime.Stderr, "Cancelled. No commit was created.")
691: 		return int(output.UserCancel)
692: 	}
693: 	if err := executeInteractiveRepair(runtime, scope, resolvedConfig, message); err != nil {
694: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
695: 		return int(output.Error)
696: 	}
697: 	executionScope := filterScopeByPaths(scope, result.ScopeFiles)
698: 	commitPlan, err := autoCommitPlanFromTUIPlan(result.CommitPlan, executionScope)
699: 	if err != nil {
700: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
701: 		return int(output.Error)
702: 	}
703: 	execution, err := executeCommitPlan(runtime, executionScope, autoArgs{NoVerify: parsed.NoVerify}, commitPlan)
704: 	if err != nil {
705: 		fmt.Fprintf(runtime.Stderr, "error: %v\n", err)
706: 		return int(output.Error)
707: 	}
708: 	commitResult := execution.lastResult()
709: 	if commitResult.Git.ExitCode != 0 {
710: 		fmt.Fprintln(runtime.Stderr, firstNonEmptyString(commitResult.Git.Stderr, commitResult.Git.Stdout, "git commit failed"))
711: 		return int(output.Error)
712: 	}
713: 	fmt.Fprintf(runtime.Stdout, "Committed %s %s\n", commitResult.Hash, commitResult.Message)
714: 	return int(output.Success)
715: }
