727: func executeInteractiveRepair(runtime Runtime, scope gitpkg.CommitScope, resolvedConfig config.EffectiveConfig, reason string) error {
728: 	provider, err := resolveRepairProvider(runtime, scope, resolvedConfig, reason)
729: 	if err != nil {
730: 		return err
731: 	}
732: 	eligiblePaths := conflictFilePaths(scope)
733: 	if len(eligiblePaths) == 0 {
734: 		return fmt.Errorf("Interactive Repair requires at least one eligible conflicted file")
735: 	}
736: 	repairRuntime := runtimex.NewToolCallRuntime(runtimex.ToolCallRuntimeOptions{
737: 		Provider:      provider,
738: 		ContextPolicy: scope.ContextPolicy,
739: 		Tools:         interactiveRepairDomainTools(runtime, scope, eligiblePaths),
740: 		RepairPolicy: runtimex.RepairPolicy{
741: 			AllowedPaths: eligiblePaths,
742: 			ConfirmWrite: func(input runtimex.RepairFileInput) (bool, error) {
743: 				return true, nil
744: 			},
745: 		},
746: 	})
747: 	result, err := repairRuntime.Run()
748: 	if err != nil {
749: 		return err
750: 	}
751: 	if result.Status != runtimex.RunStatusCompleted {
752: 		return fmt.Errorf("Interactive Repair did not complete: %s", firstNonEmptyString(result.Message, result.LimitReason, string(result.Status)))
753: 	}
754: 	return nil
755: }
