757: func resolveRepairProvider(runtime Runtime, scope gitpkg.CommitScope, resolvedConfig config.EffectiveConfig, reason string) (runtimex.ToolCallProvider, error) {
758: 	if runtime.RepairProvider != nil {
759: 		return runtime.RepairProvider, nil
760: 	}
761: 	providerConfig := providers.ProviderConfig{
