848: 		RepairFile: func(input runtimex.RepairFileInput) (runtimex.RepairFileResult, error) {
849: 			relativePath, err := requireAllowedRepairPath(input.Path, allowed)
850: 			if err != nil {
851: 				return runtimex.RepairFileResult{}, err
852: 			}
853: 			absolutePath, err := repoFilePath(runtime.CWD, relativePath)
