  1: package providers
  2: 
  3: import (
  4: 	"encoding/json"
  5: 	"fmt"
  6: 	"strings"
  7: 
  8: 	"github.com/ByteTrue/commit-now-myfriend/internal/config"
  9: 	runtimex "github.com/ByteTrue/commit-now-myfriend/internal/runtime"
 10: )
 11: 
 12: type toolProtocolAdapter struct {
 13: 	provider     config.ProviderType
 14: 	capability   ProviderCapability
 15: 	buildInitial func([]runtimex.ToolName) ([]byte, error)
 16: 	parse        func([]byte) (runtimex.ProviderTurn, error)
 17: 	build        func([]runtimex.ToolCallResult) ([]byte, error)
 18: }
 19: 
 20: func (a toolProtocolAdapter) Provider() config.ProviderType  { return a.provider }
 21: func (a toolProtocolAdapter) Capability() ProviderCapability { return a.capability }
 22: func (a toolProtocolAdapter) BuildInitialRequest(tools []runtimex.ToolName) ([]byte, error) {
 23: 	return a.buildInitial(tools)
 24: }
 25: func (a toolProtocolAdapter) ParseTurn(payload []byte) (runtimex.ProviderTurn, error) {
 26: 	return a.parse(payload)
 27: }
 28: func (a toolProtocolAdapter) BuildToolResultPayload(results []runtimex.ToolCallResult) ([]byte, error) {
 29: 	return a.build(results)
 30: }
 31: 
 32: var providerCapabilities = map[config.ProviderType]ProviderCapability{
 33: 	config.ProviderOpenAIResponses:  {Provider: config.ProviderOpenAIResponses, Protocol: "openai_responses", NativeToolCalls: true, StreamingProgress: true, InteractiveRepair: true},
 34: 	config.ProviderOpenAICompatible: {Provider: config.ProviderOpenAICompatible, Protocol: "openai_compatible_chat", NativeToolCalls: true, StreamingProgress: true, InteractiveRepair: true},
 35: 	config.ProviderAnthropic:        {Provider: config.ProviderAnthropic, Protocol: "anthropic_messages", NativeToolCalls: true, StreamingProgress: true, InteractiveRepair: true},
 36: 	config.ProviderGoogleGemini:     {Provider: config.ProviderGoogleGemini, Protocol: "google_gemini", NativeToolCalls: true, StreamingProgress: true, InteractiveRepair: true},
 37: }
 38: 
 39: func CapabilityForProvider(provider config.ProviderType) (ProviderCapability, bool) {
 40: 	capability, ok := providerCapabilities[provider]
 41: 	return capability, ok
 42: }
 43: 
 44: func CreateToolProtocolAdapter(cfg ProviderConfig) (ToolProtocolAdapter, error) {
 45: 	capability, ok := CapabilityForProvider(cfg.Provider)
 46: 	if !ok {
 47: 		return nil, fmt.Errorf("unsupported provider protocol: %s", cfg.Provider)
 48: 	}
 49: 	switch cfg.Provider {
 50: 	case config.ProviderOpenAIResponses:
 51: 		return toolProtocolAdapter{provider: cfg.Provider, capability: capability, buildInitial: buildOpenAIResponsesInitialRequest, parse: parseOpenAIResponsesTurn, build: buildOpenAIResponsesToolResultPayload}, nil
 52: 	case config.ProviderOpenAICompatible:
 53: 		return toolProtocolAdapter{provider: cfg.Provider, capability: capability, buildInitial: buildOpenAICompatibleInitialRequest, parse: parseOpenAICompatibleTurn, build: buildOpenAICompatibleToolResultPayload}, nil
 54: 	case config.ProviderAnthropic:
 55: 		return toolProtocolAdapter{provider: cfg.Provider, capability: capability, buildInitial: buildAnthropicInitialRequest, parse: parseAnthropicTurn, build: buildAnthropicToolResultPayload}, nil
 56: 	case config.ProviderGoogleGemini:
 57: 		return toolProtocolAdapter{provider: cfg.Provider, capability: capability, buildInitial: buildGeminiInitialRequest, parse: parseGeminiTurn, build: buildGeminiToolResultPayload}, nil
 58: 	default:
 59: 		return nil, fmt.Errorf("unsupported provider protocol: %s", cfg.Provider)
 60: 	}
 61: }
 62: 
 63: func parseOpenAIResponsesTurn(payload []byte) (runtimex.ProviderTurn, error) {
 64: 	var response struct {
 65: 		Output []struct {
 66: 			Type      string `json:"type"`
 67: 			CallID    string `json:"call_id"`
 68: 			Name      string `json:"name"`
 69: 			Arguments string `json:"arguments"`
 70: 		} `json:"output"`
 71: 	}
 72: 	if err := json.Unmarshal(payload, &response); err != nil {
 73: 		return runtimex.ProviderTurn{}, err
 74: 	}
 75: 	calls := make([]runtimex.ToolCallRequest, 0)
 76: 	for _, item := range response.Output {
 77: 		if item.Type != "function_call" {
 78: 			continue
 79: 		}
 80: 		arguments, err := parseToolArgumentsString(item.Arguments)
 81: 		if err != nil {
 82: 			return runtimex.ProviderTurn{}, err
 83: 		}
 84: 		calls = append(calls, runtimex.ToolCallRequest{ID: item.CallID, Name: runtimex.ToolName(item.Name), Arguments: arguments})
 85: 	}
 86: 	return runtimex.ProviderTurn{ToolCalls: calls}, nil
 87: }
 88: 
 89: func buildOpenAIResponsesInitialRequest(tools []runtimex.ToolName) ([]byte, error) {
 90: 	return json.Marshal(map[string]any{"tools": openAIResponsesFunctionTools(tools)})
 91: }
 92: 
 93: func buildOpenAIResponsesToolResultPayload(results []runtimex.ToolCallResult) ([]byte, error) {
 94: 	items := make([]map[string]any, 0, len(results))
 95: 	for _, result := range results {
 96: 		output, err := encodeToolResult(result)
 97: 		if err != nil {
 98: 			return nil, err
 99: 		}
100: 		items = append(items, map[string]any{"type": "function_call_output", "call_id": result.CallID, "output": output})
101: 	}
102: 	return json.Marshal(map[string]any{"input": items})
103: }
104: 
105: func parseOpenAICompatibleTurn(payload []byte) (runtimex.ProviderTurn, error) {
106: 	var response struct {
107: 		Choices []struct {
108: 			Message struct {
109: 				ToolCalls []struct {
110: 					ID       string `json:"id"`
111: 					Type     string `json:"type"`
112: 					Function struct {
113: 						Name      string `json:"name"`
114: 						Arguments string `json:"arguments"`
115: 					} `json:"function"`
116: 				} `json:"tool_calls"`
117: 			} `json:"message"`
118: 		} `json:"choices"`
119: 	}
120: 	if err := json.Unmarshal(payload, &response); err != nil {
121: 		return runtimex.ProviderTurn{}, err
122: 	}
123: 	calls := make([]runtimex.ToolCallRequest, 0)
124: 	for _, choice := range response.Choices {
125: 		for _, call := range choice.Message.ToolCalls {
126: 			if call.Type != "" && call.Type != "function" {
127: 				continue
128: 			}
129: 			arguments, err := parseToolArgumentsString(call.Function.Arguments)
130: 			if err != nil {
131: 				return runtimex.ProviderTurn{}, err
132: 			}
133: 			calls = append(calls, runtimex.ToolCallRequest{ID: call.ID, Name: runtimex.ToolName(call.Function.Name), Arguments: arguments})
134: 		}
135: 	}
136: 	return runtimex.ProviderTurn{ToolCalls: calls}, nil
137: }
138: 
139: func buildOpenAICompatibleToolResultPayload(results []runtimex.ToolCallResult) ([]byte, error) {
140: 	messages := make([]map[string]any, 0, len(results))
141: 	for _, result := range results {
142: 		content, err := encodeToolResult(result)
143: 		if err != nil {
144: 			return nil, err
145: 		}
146: 		messages = append(messages, map[string]any{"role": "tool", "tool_call_id": result.CallID, "content": content})
147: 	}
148: 	return json.Marshal(map[string]any{"messages": messages})
149: }
150: 
151: func buildOpenAICompatibleInitialRequest(tools []runtimex.ToolName) ([]byte, error) {
152: 	return json.Marshal(map[string]any{"tools": openAIFunctionTools(tools)})
153: }
154: 
155: func parseAnthropicTurn(payload []byte) (runtimex.ProviderTurn, error) {
156: 	var response struct {
157: 		Content []struct {
158: 			Type  string         `json:"type"`
159: 			ID    string         `json:"id"`
160: 			Name  string         `json:"name"`
161: 			Input map[string]any `json:"input"`
162: 		} `json:"content"`
163: 	}
164: 	if err := json.Unmarshal(payload, &response); err != nil {
165: 		return runtimex.ProviderTurn{}, err
166: 	}
167: 	calls := make([]runtimex.ToolCallRequest, 0)
168: 	for _, block := range response.Content {
169: 		if block.Type != "tool_use" {
170: 			continue
171: 		}
172: 		calls = append(calls, runtimex.ToolCallRequest{ID: block.ID, Name: runtimex.ToolName(block.Name), Arguments: cloneArguments(block.Input)})
173: 	}
174: 	return runtimex.ProviderTurn{ToolCalls: calls}, nil
175: }
176: 
177: func buildAnthropicToolResultPayload(results []runtimex.ToolCallResult) ([]byte, error) {
178: 	content := make([]map[string]any, 0, len(results))
179: 	for _, result := range results {
180: 		toolResult, err := toolResultObject(result)
181: 		if err != nil {
182: 			return nil, err
183: 		}
184: 		content = append(content, map[string]any{"type": "tool_result", "tool_use_id": result.CallID, "content": []map[string]any{{"type": "text", "text": toolResult}}})
185: 	}
186: 	return json.Marshal(map[string]any{"messages": []map[string]any{{"role": "user", "content": content}}})
187: }
188: 
189: func buildAnthropicInitialRequest(tools []runtimex.ToolName) ([]byte, error) {
190: 	items := make([]map[string]any, 0, len(tools))
191: 	for _, tool := range tools {
192: 		items = append(items, map[string]any{
193: 			"name":         string(tool),
194: 			"description":  toolDescription(tool),
195: 			"input_schema": toolSchema(tool),
196: 		})
197: 	}
198: 	return json.Marshal(map[string]any{"tools": items})
199: }
200: 
201: func parseGeminiTurn(payload []byte) (runtimex.ProviderTurn, error) {
202: 	var response struct {
203: 		Candidates []struct {
204: 			Content struct {
205: 				Parts []struct {
