1005: func executeAutoCommit(runtime Runtime, scope gitpkg.CommitScope, parsed autoArgs, resolvedConfig config.EffectiveConfig) (autoCommitExecution, error) {
1006: 	provider, err := resolveCommitProvider(runtime, scope, parsed, resolvedConfig)
1007: 	if err != nil {
1008: 		return autoCommitExecution{}, err
1009: 	}
1010: 	commitRuntime := runtimex.NewToolCallRuntime(runtimex.ToolCallRuntimeOptions{
1011: 		Provider:      provider,
1012: 		ContextPolicy: scope.ContextPolicy,
1013: 		Tools:         autonomousCommitDomainTools(runtime, scope, parsed),
1014: 		Limits:        runtimex.LoopLimits{MaxToolCalls: 48, MaxProviderRetries: 1, MaxDuration: 5 * time.Minute},
1015: 	})
1016: 	result, err := commitRuntime.Run()
1017: 	if err != nil {
1018: 		return autoCommitExecution{}, err
1019: 	}
1020: 	execution, ok := autoCommitExecutionFromToolCalls(result.Calls)
1021: 	if !ok {
1022: 		return autoCommitExecution{}, fmt.Errorf("Autonomous Commit did not create or preview commits: %s", firstNonEmptyString(result.Message, result.LimitReason, string(result.Status)))
1023: 	}
1024: 	if result.Status != runtimex.RunStatusCompleted {
1025: 		last := execution.lastResult()
1026: 		if last.Git.ExitCode != 0 {
